#include "tensorrt_backend.hpp"
#include "frame_scheduler.hpp"
#include "postprocess.hpp"
#include <opencv2/imgcodecs.hpp>
#include <opencv2/imgproc.hpp>
#include <opencv2/videoio.hpp>
#include <chrono>
#include <cstdlib>
#include <deque>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <numeric>
#include <sstream>
struct Pending{size_t slot;std::chrono::steady_clock::time_point submitted;};
int main(int argc,char**argv){if(argc<3){std::cerr<<"usage: integrated_tensorrt_video_pipeline_gpu ENGINE IMAGE [FRAMES=16] [BATCH=4] [SLOTS=2] [OUTPUT]\n";return 2;}try{int frames=argc>3?std::stoi(argv[3]):16,batch=argc>4?std::stoi(argv[4]):4,slot_count=argc>5?std::stoi(argv[5]):2;std::filesystem::path out=argc>6?argv[6]:"21_integrated_tensorrt_video_pipeline/output";std::string overload=argc>7?argv[7]:"block";int queue_capacity=argc>8?std::stoi(argv[8]):4;int capture_interval_ms=argc>9?std::stoi(argv[9]):0;std::string scheduling=argc>10?argv[10]:"round-robin";if(frames<1||batch<1||batch>4||slot_count<1)throw std::invalid_argument("invalid configuration");std::vector<std::vector<cv::Mat>> sources;std::stringstream source_list(argv[2]);std::string source_path;while(std::getline(source_list,source_path,',')){std::vector<cv::Mat> sequence;cv::Mat loaded=cv::imread(source_path);if(!loaded.empty())sequence.push_back(std::move(loaded));else{cv::VideoCapture capture(source_path);cv::Mat frame;while(sequence.size()<(size_t)frames&&capture.read(frame))sequence.push_back(frame.clone());}if(sequence.empty())throw std::runtime_error("cannot read source: "+source_path);sources.push_back(std::move(sequence));}if(sources.empty())throw std::runtime_error("no sources");const cv::Mat&image=sources.front().front();std::filesystem::create_directories(out);std::ofstream detections(out/"detections.jsonl"),metrics(out/"metrics.json");if(!detections||!metrics)throw std::runtime_error("cannot open outputs");lesson21::TensorRtBackend backend(argv[1],slot_count,{640,640});lesson21::OverloadPolicy overload_policy=overload=="drop-oldest"?lesson21::OverloadPolicy::DropOldest:lesson21::OverloadPolicy::Block;lesson21::SchedulingPolicy scheduling_policy=scheduling=="latest-first"?lesson21::SchedulingPolicy::LatestFirst:lesson21::SchedulingPolicy::RoundRobin;lesson21::FrameScheduler scheduler(sources,frames/sources.size(),queue_capacity,overload_policy,std::chrono::milliseconds(capture_interval_ms),scheduling_policy);scheduler.start();std::deque<size_t> free;for(int i=0;i<slot_count;++i)free.push_back(i);std::deque<Pending> pending;std::uint64_t next_frame=0,next_batch=0,processed=0;std::vector<float> latencies;double preprocess=0,inference=0,d2h=0;auto start=std::chrono::steady_clock::now();auto collect=[&](Pending p){auto result=backend.collect(p.slot);if(const char*fail=std::getenv("LESSON21_FAIL_POSTPROCESS_BATCH");fail&&result.metadata.batch_id==(std::uint64_t)std::stoull(fail))throw std::runtime_error("injected postprocess failure");free.push_back(p.slot);size_t n=result.metadata.frames.size(),per=result.output.size()/n;for(size_t i=0;i<n;++i){std::vector<float> slice(result.output.begin()+i*per,result.output.begin()+(i+1)*per);const auto&t=result.metadata.frames[i].transform;lesson11::LetterboxInfo info{t.source_width,t.source_height,640,640,(int)std::round(t.source_width*t.scale),(int)std::round(t.source_height*t.scale),(int)t.pad_x,(int)t.pad_y,0,0,t.scale};auto found=lesson11::decode_yolov8_output(slice,{1,result.output_shape[1],result.output_shape[2]},info,{});if(result.metadata.batch_id==0&&i==0){cv::Mat annotated=image.clone();for(const auto&d:found)cv::rectangle(annotated,{(int)d.box.x1,(int)d.box.y1},{(int)d.box.x2,(int)d.box.y2},{0,255,0},2);if(!cv::imwrite((out/"annotated_0.jpg").string(),annotated))throw std::runtime_error("cannot save annotation");}detections<<"{\"stream_id\":"<<result.metadata.frames[i].stream_id<<",\"frame_id\":"<<result.metadata.frames[i].frame_id<<",\"batch_id\":"<<result.metadata.batch_id<<",\"detections\":[";for(size_t d=0;d<found.size();++d){if(d)detections<<',';detections<<"{\"class_id\":"<<found[d].class_id<<",\"confidence\":"<<found[d].confidence<<",\"box\":["<<found[d].box.x1<<','<<found[d].box.y1<<','<<found[d].box.x2<<','<<found[d].box.y2<<"]}";}detections<<"]}\n";latencies.push_back(std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-result.metadata.frames[i].captured_at).count());++processed;}preprocess+=result.preprocess_ms;inference+=result.inference_ms;d2h+=result.d2h_ms;};while(!scheduler.done()||!pending.empty()){while(!free.empty()){auto scheduled=scheduler.next_batch(batch,std::chrono::milliseconds(4));if(scheduled.empty())break;size_t slot=free.front();free.pop_front();std::vector<cv::Mat> images;lesson21::BatchMetadata m;m.batch_id=next_batch++;for(auto&frame:scheduled){images.push_back(frame.image);m.frames.push_back(frame.metadata);}if(const char*fail=std::getenv("LESSON21_FAIL_SUBMIT_BATCH");fail&&m.batch_id==(std::uint64_t)std::stoull(fail))throw std::runtime_error("injected submit failure");backend.submit(slot,images,std::move(m));pending.push_back({slot,std::chrono::steady_clock::now()});next_frame+=images.size();}bool collected=false;for(auto it=pending.begin();it!=pending.end();++it)if(backend.ready(it->slot)){auto p=*it;pending.erase(it);collect(p);collected=true;break;}if(!collected&&!pending.empty()){auto p=pending.front();pending.pop_front();collect(p);}}scheduler.stop(false);auto elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();std::sort(latencies.begin(),latencies.end());auto pct=[&](double q){return latencies.empty()?0.0:latencies[(size_t)((latencies.size()-1)*q)];};metrics<<"{\"schema_version\":1,\"captured\":"<<scheduler.captured()<<",\"admitted\":"<<next_frame<<",\"submitted\":"<<next_frame<<",\"completed\":"<<processed<<",\"processed\":"<<processed<<",\"queue_peak\":"<<scheduler.queue_peak()<<",\"dropped\":"<<scheduler.evicted()<<",\"batches\":"<<next_batch<<",\"slots\":"<<slot_count<<",\"overload_policy\":\""<<overload<<"\",\"scheduling_policy\":\""<<scheduling<<"\""<<",\"preprocess_ms\":"<<preprocess<<",\"inference_ms\":"<<inference<<",\"d2h_ms\":"<<d2h<<",\"p50_ms\":"<<pct(.5)<<",\"p90_ms\":"<<pct(.9)<<",\"p99_ms\":"<<pct(.99)<<",\"fps\":"<<processed/elapsed<<"}\n";std::cout<<"backend=tensorrt captured="<<scheduler.captured()<<" processed="<<processed<<" dropped="<<scheduler.evicted()<<" batches="<<next_batch<<" slots="<<slot_count<<" fps="<<processed/elapsed<<" p50_ms="<<pct(.5)<<" p90_ms="<<pct(.9)<<" p99_ms="<<pct(.99)<<'\n';return processed+scheduler.evicted()==scheduler.captured()?0:1;}catch(const std::exception&e){std::cerr<<"error: "<<e.what()<<'\n';return 1;}}
